catalog_script_client.script:
function applyInputMasks() {

	var maskConfigs = [
		{
			selector: "#sp_formfield_cpf_solicitante",
			mask: "999.999.999-99",
			options: {
				showMaskOnHover: false,
				showMaskOnFocus: false
			}
		},
		{
			selector: "#sp_formfield_nome_solicitante",
			regex: "^[A-Za-zÀ-ÿ\\s]*$",
			options: {
				showMaskOnHover: false,
				showMaskOnFocus: false
			}
		}
	];

	maskConfigs.forEach(function (config) {

		var field = this.document.querySelector(config.selector);

		if (field) {
			var maskOpts = {
				showMaskOnHover: config.options ? config.options.showMaskOnHover : false,
				showMaskOnFocus: config.options ? config.options.showMaskOnFocus : false
			};

			if (config.mask) {
				maskOpts.mask = config.mask;
			} else if (config.regex) {
				maskOpts.regex = config.regex;
			}

			Inputmask(maskOpts).mask(field);

			// Re-aplica no colar
			field.addEventListener('paste', function () {
				setTimeout(function () {
					Inputmask(maskOpts).mask(field);
					field.dispatchEvent(new Event('change', { bubbles: true }));
				}, 0);
			});
		}
	});
}

function onLoad() {
	setTimeout(function () {
		applyInputMasks();
	}, 500);
}
